WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY monthly_fee NULLS FIRST, id) AS rank_in_group FROM subscriptions) t WHERE rank_in_group = 1) SELECT DATE_TRUNC('QUARTER', start_date) AS quarter_start, DATE_TRUNC('MONTH', end_date) AS activity_month, PERCENTILE_APPROX(monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_quartiles, APPROX_PERCENTILE(monthly_fee, 0.5) AS monthly_fee_p50, PERCENTILE_APPROX(monthly_fee, 0.9) AS monthly_fee_p90 FROM deduped GROUP BY DATE_TRUNC('QUARTER', start_date), DATE_TRUNC('MONTH', end_date) ORDER BY monthly_fee_p90 DESC
